{
  "name": "claude-mem-grok-bot",
  "version": "13.23.1",
  "description": "Persistent memory for Grok Bot. No host hooks: transcript watcher plus MCP. Local worker with host-login observer, or remote cmem.ai. Install without Cursor.",
  "author": { "name": "Alex Newman" },
  "homepage": "https://github.com/thedotmack/claude-mem",
  "repository": "https://github.com/thedotmack/claude-mem",
  "license": "Apache-2.0",
  "keywords": ["claude-mem", "memory", "grok-bot", "mcp", "cmem"],
  "category": "MCP",
  "skills": "./skills/",
  "mcpServers": "./mcp.json",
  "variables": {
    "type": "object",
    "properties": {
      "CLAUDE_MEM_MCP_URL": {
        "type": "string",
        "title": "Remote MCP URL",
        "description": "Leave empty for a local worker (stdio). Set to https://cmem.ai/api/mcp for remote."
      },
      "CLAUDE_MEM_MCP_TOKEN": {
        "type": "string",
        "title": "Remote MCP token",
        "description": "Bearer token for remote MCP. Unused for local worker."
      }
    },
    "required": []
  }
}
